@EventBusSubscriber(modid=EMT.MODID)
public final class ServerAudit {
 private static final boolean ON="server".equals(System.getProperty("emt.audit"));private static int tick,checks,failed;private static BlockPos base;private static final List<BlockPos> solars=new ArrayList<>(),generators=new ArrayList<>();private static BlockPos linkedCharger;
 public static void check(String name,boolean ok,Object detail){checks++;if(!ok)failed++;EMT.LOG.info("[emt-audit] {} {} {}",ok?"PASS":"FAIL",name,detail);}
 private static TileSolar solar(ServerLevel l,int kind,int stage){return (TileSolar)l.getBlockEntity(solars.get(kind*3+stage));}
 @SubscribeEvent static void start(ServerStartedEvent e){if(!ON)return;var l=e.getServer().overworld();for(long key:l.getForcedChunks().toLongArray())l.setChunkForced(ChunkPos.getX(key),ChunkPos.getZ(key),false);base=new BlockPos(2000+l.random.nextInt(1000),180,2000+l.random.nextInt(1000));for(int x=-1;x<=4;x++)for(int z=-1;z<=4;z++)l.setChunkForced((base.getX()>>4)+x,(base.getZ()>>4)+z,true);l.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,e.getServer());l.getGameRules().getRule(GameRules.RULE_WEATHER_CYCLE).set(false,e.getServer());l.setDayTime(6000);l.setWeatherParameters(6000,0,false,false);HammerAudit.prepare(l,base);
  int n=0;for(var entry:EMTBlocks.MACHINES.entrySet()){var p=base.offset(n%7*7,0,n/7*8);l.setBlock(p,entry.getValue().get().defaultBlockState(),3);if(entry.getKey().endsWith("_solar"))solars.add(p);if(entry.getKey().endsWith("_generator"))generators.add(p);n++;}
  l.setBlock(base.below(),Ic2Blocks.BATBOX.get().defaultBlockState(),3);
  linkedCharger=base.offset(0,0,40);l.setBlock(linkedCharger,EMTBlocks.block("industrial_wand_charger").defaultBlockState(),3);var wand=EMTRecipes.stack("tc4modern:wand");((TileWandCharger)l.getBlockEntity(linkedCharger)).wand.put(wand);
  l.setBlock(linkedCharger.west(),Ic2Blocks.MFSU.get().defaultBlockState().setValue(BlockTileEntity.FACING,Direction.EAST),3);((TileEntityElectricBlock)l.getBlockEntity(linkedCharger.west())).energy=200000;
  for(var p:generators){var g=(TileEssentiaGenerator)l.getBlockEntity(p);l.setBlock(p.above(2),EssentiaDevices.JAR.get().defaultBlockState(),3);AspectContainers.find(l,p.above(2)).add(g.aspect,1);}
 }
 @SubscribeEvent static void tick(ServerTickEvent.Post e){if(!ON)return;tick++;var l=e.getServer().overworld();HammerAudit.tick(l,tick);
  if(tick==5){for(int k=0;k<7;k++)for(int s=0;s<3;s++){var tile=solar(l,k,s);tile.checkSun();double expected=EMTConfig.SOLAR[s].get()*(k==3?3:k==5?2.5:1);if(k==1||k==2||k==4)expected=0;check("solar day "+tile.kind+" stage"+s,tile.generation()==expected,tile.generation());}}
  if(tick==120){check("EMT compressed solar supplies real IC2 BatBox",((TileEntityElectricBlock)l.getBlockEntity(base.below())).energy>100,((TileEntityElectricBlock)l.getBlockEntity(base.below())).energy);var charger=(TileWandCharger)l.getBlockEntity(linkedCharger);check("real IC2 MFSU charges Thaumcraft wand through EMT",WandData.get(charger.wand.get(),Aspect.AIR)>0,WandData.get(charger.wand.get(),Aspect.AIR));run(l);ToolAudit.run(l,base);ArmorAudit.run(l,base);WingEnvironmentAudit.run(l,base);FocusAudit.run(l,base);RingsAudit.run(l,base);HammerAudit.run(l,base);NodeCloudAudit.run(l,base);ParityAudit.run(l,base);CommandAudit.run(l,base);ShearsAudit.run(l,base);l.setDayTime(18000);}
  if(tick==122){ArmorAudit.night(l,base);var dark=solar(l,2,0);dark.checkSun();check("entropy solar works on clear night",dark.generation()==10,dark.generation());var compressed=solar(l,0,0);compressed.checkSun();check("compressed solar stops at night",compressed.generation()==0,compressed.generation());l.setDayTime(6000);l.setWeatherParameters(0,6000,true,true);}
  if(tick==190){var water=solar(l,1,0);water.checkSun();check("water solar generates in rain",water.generation()==10,water.generation());var dark=solar(l,2,0);dark.checkSun();check("entropy solar stops in rain",dark.generation()==0,dark.generation());var normal=solar(l,0,0);normal.checkSun();check("ordinary solar respects wet biome rain",!l.getBiome(normal.getBlockPos()).value().hasPrecipitation()||normal.generation()==0,normal.generation());l.setWeatherParameters(6000,0,false,false);EMT.LOG.info("[emt-audit] DONE {} checks, {} failed",checks,failed);e.getServer().halt(false);}
 }
 private static void run(ServerLevel l){
  var tile=solar(l,0,1);tile.checkSun();l.setBlock(tile.getBlockPos().above(),Blocks.STONE.defaultBlockState(),3);tile.checkSun();check("opaque roof stops compressed solar",tile.generation()==0,tile.generation());l.removeBlock(tile.getBlockPos().above(),false);tile.checkSun();tile.energy=9999;tile.addEnergy(1e12);check("solar capacity clamps",tile.energy==10000,tile.energy);tile.energy=123.5;var copy=(TileSolar)BlockEntity.loadStatic(tile.getBlockPos(),tile.getBlockState(),tile.saveWithFullMetadata(l.registryAccess()),l.registryAccess());check("solar fractional energy persists",copy.energy==123.5,copy.energy);
  var low=base.offset(48,-175,0);l.setBlock(low,EMTBlocks.block("earth_solar").defaultBlockState(),3);var earth=(TileSolar)l.getBlockEntity(low);earth.checkSun();check("earth solar original low height bonus",earth.generation()==25,earth.generation());
  var nether=l.getServer().getLevel(Level.NETHER);var pos=new BlockPos(0,130,0);nether.setChunkForced(0,0,true);nether.setBlock(pos,EMTBlocks.block("fire_solar").defaultBlockState(),3);var fire=(TileSolar)nether.getBlockEntity(pos);check("fire solar generates only in Nether at double output",fire.generation()==20,fire.generation());nether.setBlock(pos.east(),EMTBlocks.block("compressed_solar").defaultBlockState(),3);var noSky=(TileSolar)nether.getBlockEntity(pos.east());noSky.checkSun();check("normal solar cannot generate without skylight",noSky.generation()==0,noSky.generation());
  for(var p:generators){var g=(TileEssentiaGenerator)l.getBlockEntity(p);check("generator drains real TC jar for "+g.aspect.getTag(),AspectContainers.find(l,p.above(2)).stored()==0&&Math.abs(g.energy-EMTConfig.essentiaOutput(g.aspect)/30)<.000001,g.energy);var saved=(TileEssentiaGenerator)BlockEntity.loadStatic(p,g.getBlockState(),g.saveWithFullMetadata(l.registryAccess()),l.registryAccess());check("essentia generator energy persists "+g.aspect.getTag(),saved.energy==g.energy,saved.energy);var jar=AspectContainers.find(l,p.above(2));jar.add(g.aspect,1);g.energy=g.capacity-EMTConfig.essentiaOutput(g.aspect)/60;check("full generator preserves essentia "+g.aspect.getTag(),g.createEnergy()==0&&jar.stored()==1,jar.stored());jar.take(g.aspect,1);}
  double cap=EMTConfig.OUTPUT_CAP.get();EMTConfig.OUTPUT_CAP.set(1000d);check("compound output cap keeps defined lower outputs",EMTConfig.essentiaOutput(Aspect.ENERGY)==1000&&EMTConfig.essentiaOutput(Aspect.FIRE)==20000,EMTConfig.essentiaOutput(Aspect.ENERGY));EMTConfig.OUTPUT_CAP.set(cap);
  var c=(TileWandCharger)l.getBlockEntity(linkedCharger);c.wand.put(EMTRecipes.stack("tc4modern:wand"));c.energy=50000;check("charger converts EU into one vis of each primal",c.chargeWand()&&c.energy==0&&Aspect.getPrimalAspects().stream().allMatch(a->WandData.get(c.wand.get(),a)==100),c.energy);for(var a:Aspect.getPrimalAspects())WandData.add(c.wand.get(),a,WandData.capacity(c.wand.get()),true);c.energy=50000;check("full wand does not waste EU",!c.chargeWand()&&c.energy==50000,c.energy);check("wand slot rejects non-wands",!c.wand.accepts(new ItemStack(Items.STICK)),"filtered");check("TC relay finds EMT held wand",TC4Addons.heldWand(c)==c.wand.get(),"API holder");c.energy=12345.5;var saved=(TileWandCharger)BlockEntity.loadStatic(c.getBlockPos(),c.getBlockState(),c.saveWithFullMetadata(l.registryAccess()),l.registryAccess());check("charger preserves EU and wand",saved.energy==12345.5&&WandData.get(saved.wand.get(),Aspect.AIR)==WandData.capacity(saved.wand.get()),saved.energy);c.energy=99990;check("charger returns excess injected EU",c.injectEnergy(Direction.UP,100,2048)==90&&c.energy==100000,c.energy);
  var p=base.offset(48,0,32);l.setBlock(p,EMTBlocks.block("ethereal_processor").defaultBlockState(),3);var proc=(TileEtherealProcessor)l.getBlockEntity(p);check("processor rejects forbidden and non-smeltable automation input",!proc.input.accepts(new ItemStack(Items.POTATO))&&!proc.input.accepts(new ItemStack(Items.STICK))&&proc.input.accepts(new ItemStack(Items.RAW_IRON)),"filtered");check("processor original sided automation",proc.canPlaceItemThroughFace(0,new ItemStack(Items.RAW_IRON),Direction.UP)&&!proc.canPlaceItemThroughFace(0,new ItemStack(Items.RAW_IRON),Direction.NORTH)&&proc.canTakeItemThroughFace(1,ItemStack.EMPTY,Direction.NORTH)&&!proc.canTakeItemThroughFace(2,ItemStack.EMPTY,Direction.NORTH),"top input, bottom outputs, side bonus");proc.input.put(new ItemStack(Items.RAW_IRON));int chance=EMTConfig.BONUS_CHANCE.get();EMTConfig.BONUS_CHANCE.set(1);for(int i=0;i<400;i++)proc.processTick();EMTConfig.BONUS_CHANCE.set(chance);check("processor doubles smelting with last-input bonus",proc.input.isEmpty()&&proc.output.get().is(Items.IRON_INGOT)&&proc.output.get().getCount()==2&&proc.bonus.get().is(EMTRecipes.item("tc4modern:thaumium_nugget")),proc.output.get());proc.input.put(new ItemStack(Items.RAW_IRON));proc.output.put(new ItemStack(Items.IRON_INGOT,63));check("full output cannot consume processor input",!proc.processTick()&&proc.input.get().getCount()==1&&proc.progress==0,proc.output.get());proc.output.put(ItemStack.EMPTY);proc.bonus.put(ItemStack.EMPTY);proc.processTick();var ps=(TileEtherealProcessor)BlockEntity.loadStatic(p,proc.getBlockState(),proc.saveWithFullMetadata(l.registryAccess()),l.registryAccess());check("processor saves progress and inventory",ps.progress==1&&ps.input.get().is(Items.RAW_IRON),ps.progress);for(var stack:List.of(new ItemStack(Items.COBBLESTONE),new ItemStack(Items.SAND),new ItemStack(Items.POTATO),new ItemStack(Ic2Items.get("iron_dust")),new ItemStack(Items.IRON_PICKAXE)))check("processor prevents free recycling "+stack.getItem(),proc.forbidden(stack),"excluded");
  check("all original magic machine recipes registered",EMTRecipes.definitions().getAsJsonArray("recipes").size()==79&&TC4Addons.crucibleRecipes().keySet().stream().filter(k->k.startsWith("emt:")).count()==24,TC4Addons.crucibleRecipes().size());check("EMT research tab and original entries registered",ResearchCategories.getResearch("Compressed Solars")!=null&&ResearchCategories.getResearch("Etheral Processor")!=null&&ResearchCategories.getResearch("Potentia Generator").parentsHidden[0].equals("INFUSION"),"research graph");
  var actor=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(l);actor.getInventory().clearContent();var bench=base.offset(48,0,40);l.setBlock(bench,TC4Modern.ARCANE_WORKBENCH.get().defaultBlockState(),3);actor.setPos(bench.getX(),bench.getY()+1,bench.getZ());var table=new net.minecraft.world.SimpleContainer(10);var craftWand=EMTRecipes.stack("tc4modern:wand");for(var a:Aspect.getPrimalAspects())WandData.add(craftWand,a,25,true);table.setItem(9,craftWand);for(int i=0;i<9;i++)table.setItem(i,new ItemStack(Ic2Blocks.SOLAR_PANEL.get()));var menu=new ArcaneWorkbenchMenu(1,actor.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.create(l,bench),table);check("real arcane workbench rejects locked EMT research",menu.getSlot(0).getItem().isEmpty(),"locked");ResearchProgress.add(actor.getPersistentData(),"Compressed Solars");table.setChanged();int visBefore=WandData.get(craftWand,Aspect.AIR);var crafted=menu.quickMoveStack(actor,0);check("real TC workbench crafts EMT panel and spends wand vis",crafted.is(EMTBlocks.block("compressed_solar").asItem())&&table.getItem(0).isEmpty()&&WandData.get(craftWand,Aspect.AIR)<visBefore,crafted);menu.removed(actor);var crucible=TC4Addons.crucibleRecipes().get("emt:waterSolar");var selected=thaumcraft.api.crafting.CrucibleRecipe.findMatching(new ArrayList<>(TC4Addons.crucibleRecipes().values()),Set.of("Water Infused Solar Panels"),crucible.aspects.copy(),new ItemStack(EMTBlocks.block("compressed_solar")));check("native TC crucible selects registered EMT conversion",selected==crucible&&selected.getRecipeOutput().is(EMTBlocks.block("water_solar").asItem()),"crucible");
  var out=ic2.api.recipe.Recipes.macerator.getOutputFor(EMTRecipes.stack("tc4modern:iron_cluster"),false);check("native ore clusters use IC2 macerator",out!=null&&out.items.getFirst().getCount()==22,out==null?"missing":out.items);var ore=ic2.api.recipe.Recipes.macerator.getOutputFor(EMTRecipes.stack("tc4modern:deepslate_cinnabar_ore"),false);check("deepslate cinnabar has EMT crushing chain",ore!=null&&ore.items.getFirst().is(EMTItems.material("crushed_cinnabar"))&&ore.items.getFirst().getCount()==2,ore==null?"missing":ore.items);var wash=ic2.api.recipe.Recipes.oreWashing.getOutputFor(new ItemStack(EMTItems.material("crushed_amber")),false);check("ore washing uses modern IC2 fluid metadata",wash!=null&&wash.metadata.getInt("fluid")==1000&&wash.items.size()==3,wash==null?"missing":wash.items);var heat=ic2.api.recipe.Recipes.centrifuge.getOutputFor(new ItemStack(EMTItems.material("purified_cinnabar")),false);check("centrifuge uses modern IC2 heat metadata",heat!=null&&heat.metadata.getInt("heat")==1000,heat==null?"missing":heat.metadata);check("rolling thaumium plate API recipe",ic2.api.recipe.Recipes.metalformerRolling.getOutputFor(EMTRecipes.stack("tc4modern:thaumium_ingot"),false)!=null,"rolling");
 }
}
